package com.musiccatalog.service; import com.musiccatalog.dto.AnalyticsDtos.*; import com.musiccatalog.entity.Album; import com.musiccatalog.exception.ApiException; import com.musiccatalog.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.time.*; import java.util.*; import java.util.function.Function; import java.util.stream.*;
@Service public class AnalyticsService { private final AlbumRepository albums;private final UserRepository users; public AnalyticsService(AlbumRepository a,UserRepository u){albums=a;users=u;} private List<Album> list(String email){var u=users.findByEmail(email).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"User not found"));return albums.findAllByUserIdOrderByCreatedAtDesc(u.getId());} private List<Count> count(List<Album> a,Function<Album,String> f){return a.stream().map(f).filter(x->x!=null&&!x.isBlank()).collect(Collectors.groupingBy(Function.identity(),Collectors.counting())).entrySet().stream().map(x->new Count(x.getKey(),x.getValue())).sorted(Comparator.comparingLong(Count::count).reversed()).toList();} public Analytics analytics(String email){List<Album>a=list(email);Map<LocalDate,Long> byDay=a.stream().collect(Collectors.groupingBy(x->x.getCreatedAt().atZone(ZoneOffset.UTC).toLocalDate(),TreeMap::new,Collectors.counting()));long total=0;List<Growth> growth=new ArrayList<>();for(var e:byDay.entrySet()){total+=e.getValue();growth.add(new Growth(e.getKey().toString(),total));}return new Analytics(count(a,Album::getGenre),count(a,Album::getArtistName).stream().limit(10).toList(),growth,count(a,x->x.getReleaseDate()==null?null:String.valueOf(x.getReleaseDate().getYear())),a.size());} public List<Album> library(String email){return list(email);} }
